mapper.select:
SELECT is_sos_alert
  FROM users
 WHERE user_id = #{userId}

mapper.insert:
INSERT INTO sos_events (
    user_id
  , lat
  , lng
  , checklist_json
  , send_msg
) VALUES (
    #{userId}
  , #{lat}
  , #{lng}
  , #{checklistJson}
  , #{sendMsg}
)

INSERT INTO notifications (
    user_id
  , guardian_id
  , sos_id
  , noti_type
  , channel
  , title
  , body
) VALUES (
    #{userId}
  , #{guardianId}
  , #{sosId}
  , #{notiType}
  , #{channel}
  , #{title}
  , #{body}
)
